import math

def solve():
    best_n = float('inf')
    for n in range(45, 90):
        # We need 3r^2 - 3nr + n^2 - 2007 = 0 to have integer solution for r
        # Discriminant D = 9n^2 - 12(n^2 - 2007) = 24084 - 3n^2
        D = 24084 - 3 * n**2
        if D >= 0:
            sqrtD = int(math.isqrt(D))
            if sqrtD * sqrtD == D:
                # r = (3n \pm sqrtD) / 6
                if (3 * n + sqrtD) % 6 == 0:
                    r1 = (3 * n + sqrtD) // 6
                    if 0 <= r1 <= n:
                        best_n = min(best_n, n)
                if (3 * n - sqrtD) % 6 == 0:
                    r2 = (3 * n - sqrtD) // 6
                    if 0 <= r2 <= n:
                        best_n = min(best_n, n)
    return best_n

print(solve())

